#include <cstdint>
#include <vector>

struct Player
{
    std::uint32_t id;
    std::int16_t health;
    std::uint8_t level;
    std::uint32_t gold;
};

static void put(std::vector<std::uint8_t>& out, std::uint32_t value, int byteCount)
{
    for (int i{ 0 }; i < byteCount; ++i)
        out.push_back(static_cast<std::uint8_t>(value >> (8 * i)));   // lowest byte first
}

static std::uint32_t get(const std::vector<std::uint8_t>& in, int at, int byteCount)
{
    std::uint32_t value{ 0 };
    for (int i{ 0 }; i < byteCount; ++i)
        value |= static_cast<std::uint32_t>(in[at + i]) << (8 * i);
    return value;
}

std::vector<std::uint8_t> savePlayer(const Player& p)
{
    std::vector<std::uint8_t> out;
    put(out, p.id, 4);
    put(out, static_cast<std::uint16_t>(p.health), 2);
    put(out, p.level, 1);
    put(out, p.gold, 4);
    return out;
}

Player loadPlayer(const std::vector<std::uint8_t>& bytes)
{
    Player p{};
    p.id = get(bytes, 0, 4);
    p.health = static_cast<std::int16_t>(static_cast<std::uint16_t>(get(bytes, 4, 2)));
    p.level = static_cast<std::uint8_t>(get(bytes, 6, 1));
    p.gold = get(bytes, 7, 4);
    return p;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("eleven bytes, no padding") { CHECK_EQ(savePlayer(Player{ 1, 2, 3, 4 }).size(), std::size_t{ 11 }); }
TEST("the exact bytes")
{
    const Bytes b{ savePlayer(Player{ 0x01020304u, 300, 7, 1000 }) };
    CHECK(b == Bytes({ 0x04, 0x03, 0x02, 0x01, 0x2C, 0x01, 0x07, 0xE8, 0x03, 0x00, 0x00 }));
}
TEST("negative health uses two's complement")
{
    const Bytes b{ savePlayer(Player{ 0, -1, 0, 0 }) };
    CHECK_EQ(static_cast<int>(b[4]), 0xFF);
    CHECK_EQ(static_cast<int>(b[5]), 0xFF);
}
TEST("load reads the format")
{
    const Player p{ loadPlayer(Bytes{ 0x2A, 0, 0, 0, 0x9C, 0xFF, 12, 0x10, 0x27, 0, 0 }) };
    CHECK_EQ(p.id, 42u);
    CHECK_EQ(p.health, std::int16_t{ -100 });
    CHECK_EQ(static_cast<int>(p.level), 12);
    CHECK_EQ(p.gold, 10000u);
}
TEST("save then load gives the same player")
{
    const Player original{ 4000000000u, -32768, 255, 123456789u };
    const Player copy{ loadPlayer(savePlayer(original)) };
    CHECK_EQ(copy.id, original.id);
    CHECK_EQ(copy.health, original.health);
    CHECK_EQ(copy.level, original.level);
    CHECK_EQ(copy.gold, original.gold);
}

